insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000002311', 'had I known', '/hæd aɪ noʊn/', 'phrase', 'se eu tivesse sabido', 'Had I known about the delay, I would have left earlier.', 'Se eu tivesse sabido do atraso, eu teria saído mais cedo.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002312', 'were it not for', '/wɜːr ɪt nɒt fɔːr/', 'phrase', 'se não fosse por', 'Were it not for her help, the project would have failed.', 'Se não fosse pela ajuda dela, o projeto teria fracassado.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002313', 'should you require', '/ʃʊd juː rɪˈkwaɪər/', 'phrase', 'caso você precise', 'Should you require further information, please contact us.', 'Caso você precise de mais informações, entre em contato conosco.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002314', 'were I to', '/wɜːr aɪ tuː/', 'phrase', 'se eu viesse a', 'Were I to accept the offer, I would need more time to decide.', 'Se eu viesse a aceitar a oferta, precisaria de mais tempo para decidir.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002315', 'had it not been for', '/hæd ɪt nɒt bɪn fɔːr/', 'phrase', 'se não tivesse sido por', 'Had it not been for the storm, the flight would have arrived on time.', 'Se não tivesse sido pela tempestade, o voo teria chegado na hora.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002316', 'should this occur', '/ʃʊd ðɪs əˈkɜːr/', 'phrase', 'caso isso ocorra', 'Should this occur again, please report it immediately.', 'Caso isso ocorra novamente, por favor, reporte imediatamente.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002317', 'rarely have I seen', '/ˈrerli hæv aɪ siːn/', 'phrase', 'raramente eu já vi', 'Rarely have I seen such a well-organized team.', 'Raramente eu já vi uma equipe tão bem organizada.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002318', 'never before has', '/ˈnevər bɪˈfɔːr hæz/', 'phrase', 'nunca antes', 'Never before has the company faced such a challenge.', 'Nunca antes a empresa enfrentou um desafio como esse.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002319', 'not until', '/nɒt ənˈtɪl/', 'phrase', 'somente quando', 'Not until the results arrived did they understand the problem.', 'Somente quando os resultados chegaram é que eles entenderam o problema.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002320', 'only then did', '/ˈoʊnli ðen dɪd/', 'phrase', 'só então', 'Only then did she realize her mistake.', 'Só então ela percebeu o erro dela.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002321', 'seldom do we', '/ˈseldəm duː wiː/', 'phrase', 'raramente nós', 'Seldom do we see such rapid progress in this field.', 'Raramente vemos um progresso tão rápido nesta área.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002322', 'under no circumstances', '/ˈʌndər noʊ ˈsɜːrkəmstænsɪz/', 'phrase', 'em hipótese alguma', 'Under no circumstances should this document be shared externally.', 'Em hipótese alguma este documento deve ser compartilhado externamente.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002323', 'little did he know', '/ˈlɪtl dɪd hiː noʊ/', 'phrase', 'ele mal sabia', 'Little did he know that the decision would change everything.', 'Ele mal sabia que a decisão mudaria tudo.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002324', 'no sooner had... than', '/noʊ ˈsuːnər hæd ðæn/', 'phrase', 'mal... e já', 'No sooner had she arrived than the meeting started.', 'Mal ela chegou e a reunião já começou.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002325', 'hardly had... when', '/ˈhɑːrdli hæd wen/', 'phrase', 'mal... quando', 'Hardly had he finished speaking when the phone rang.', 'Ele mal tinha terminado de falar quando o telefone tocou.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002326', 'only after', '/ˈoʊnli ˈæftər/', 'phrase', 'somente depois de', 'Only after reviewing the data did they approve the plan.', 'Somente depois de revisar os dados eles aprovaram o plano.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002327', 'so great was', '/soʊ ɡreɪt wɒz/', 'phrase', 'tão grande foi', 'So great was the demand that the company doubled production.', 'Tão grande foi a demanda que a empresa dobrou a produção.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002328', 'such was the impact', '/sʌtʃ wɒz ði ˈɪmpækt/', 'phrase', 'tal foi o impacto', 'Such was the impact of the announcement that shares rose immediately.', 'Tal foi o impacto do anúncio que as ações subiram imediatamente.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002329', 'were it to happen', '/wɜːr ɪt tuː ˈhæpən/', 'phrase', 'se isso viesse a acontecer', 'Were it to happen again, the team would be better prepared.', 'Se isso viesse a acontecer de novo, a equipe estaria mais preparada.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002330', 'had they realized', '/hæd ðeɪ ˈriːəlaɪzd/', 'phrase', 'se eles tivessem percebido', 'Had they realized the risk sooner, they could have avoided the loss.', 'Se eles tivessem percebido o risco antes, poderiam ter evitado a perda.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002331', 'should the need arise', '/ʃʊd ðə niːd əˈraɪz/', 'phrase', 'caso a necessidade surja', 'Should the need arise, additional staff will be hired.', 'Caso a necessidade surja, funcionários adicionais serão contratados.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002332', 'were this the case', '/wɜːr ðɪs ðə keɪs/', 'phrase', 'se esse fosse o caso', 'Were this the case, the entire strategy would need to change.', 'Se esse fosse o caso, toda a estratégia precisaria mudar.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002333', 'had I been aware', '/hæd aɪ bɪn əˈwer/', 'phrase', 'se eu estivesse ciente', 'Had I been aware of the deadline, I would have finished sooner.', 'Se eu estivesse ciente do prazo, eu teria terminado antes.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002334', 'should there be any doubt', '/ʃʊd ðer biː ˈeni daʊt/', 'phrase', 'caso haja alguma dúvida', 'Should there be any doubt, feel free to contact the office.', 'Caso haja alguma dúvida, sinta-se à vontade para contatar o escritório.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002335', 'it goes without saying that', '/ɪt ɡoʊz wɪˈðaʊt ˈseɪɪŋ ðæt/', 'phrase', 'nem precisa dizer que', 'It goes without saying that safety comes first.', 'Nem precisa dizer que a segurança vem em primeiro lugar.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002336', 'needless to say', '/ˈniːdləs tuː seɪ/', 'phrase', 'desnecessário dizer', 'Needless to say, the client was extremely satisfied.', 'Desnecessário dizer que o cliente ficou extremamente satisfeito.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002337', 'suffice it to say', '/səˈfaɪs ɪt tuː seɪ/', 'phrase', 'basta dizer que', 'Suffice it to say, the results exceeded all expectations.', 'Basta dizer que os resultados superaram todas as expectativas.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002338', 'it stands to reason that', '/ɪt stændz tuː ˈriːzən ðæt/', 'phrase', 'é lógico que', 'It stands to reason that more training leads to better performance.', 'É lógico que mais treinamento leva a um desempenho melhor.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002339', 'in no way', '/ɪn noʊ weɪ/', 'phrase', 'de forma alguma', 'This decision in no way reflects a lack of confidence in the team.', 'Essa decisão de forma alguma reflete falta de confiança na equipe.', 'C1', array['inversion']),
('30000000-0000-0000-0000-000000002340', 'under any circumstances', '/ˈʌndər ˈeni ˈsɜːrkəmstænsɪz/', 'phrase', 'em qualquer circunstância', 'The rule applies under any circumstances, without exception.', 'A regra se aplica em qualquer circunstância, sem exceção.', 'C1', array['inversion']);

