-- Lição 386: Condicionais invertidas formais (had I known, were it not for, should you require, were I to, had it not been for, should this occur)
insert into exercises (lesson_id, type, sort_order, content) values
('20000000-0000-0000-0000-000000000386', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002311", "show_image": false}'),
('20000000-0000-0000-0000-000000000386', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002312", "show_image": false}'),
('20000000-0000-0000-0000-000000000386', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002313", "show_image": false}'),
('20000000-0000-0000-0000-000000000386', 'multiple_choice', 4, '{"question": "___ about the delay, I would have left earlier.", "audio_text": null, "options": ["Had I known", "Should this occur", "Were I to"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000386', 'multiple_choice', 5, '{"question": "___ her help, the project would have failed.", "audio_text": null, "options": ["Were it not for", "Should you require", "Had it not been for"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000386', 'matching', 6, '{"pairs": [{"left": "had I known", "right": "se eu tivesse sabido"}, {"left": "were it not for", "right": "se não fosse por"}, {"left": "should you require", "right": "caso você precise"}, {"left": "were I to", "right": "se eu viesse a"}, {"left": "had it not been for", "right": "se não tivesse sido por"}, {"left": "should this occur", "right": "caso isso ocorra"}]}'),
('20000000-0000-0000-0000-000000000386', 'fill_blank', 7, '{"sentence": "___ accept the offer, I would need more time to decide.", "options": ["Were I to", "Had I known", "Should this occur"], "correct": "Were I to", "translation": "Se eu viesse a aceitar a oferta, precisaria de mais tempo para decidir."}'),
('20000000-0000-0000-0000-000000000386', 'fill_blank', 8, '{"sentence": "___ further information, please contact us.", "options": ["Should you require", "Were it not for", "Had it not been for"], "correct": "Should you require", "translation": "Caso você precise de mais informações, entre em contato conosco."}'),
('20000000-0000-0000-0000-000000000386', 'word_order', 9, '{"words": ["Had", "it", "not", "been", "for", "the", "storm", "the", "flight", "would", "have", "arrived", "on", "time"], "correct_sentence": "Had it not been for the storm the flight would have arrived on time", "translation": "Se não tivesse sido pela tempestade, o voo teria chegado na hora"}'),
('20000000-0000-0000-0000-000000000386', 'word_order', 10, '{"words": ["Should", "this", "occur", "again", "please", "report", "it", "immediately"], "correct_sentence": "Should this occur again please report it immediately", "translation": "Caso isso ocorra novamente, por favor, reporte imediatamente"}'),
('20000000-0000-0000-0000-000000000386', 'reading', 11, '{"passage": "In very formal English, conditional sentences can drop ''if'' and invert the subject and auxiliary instead. ''If I had known'' becomes ''had I known'', ''if it were not for'' becomes ''were it not for'', and ''if you should require'' becomes ''should you require''. This structure is common in legal documents, formal speeches, and business correspondence.", "translation": "No inglês muito formal, orações condicionais podem eliminar o ''if'' e inverter o sujeito e o auxiliar. ''If I had known'' vira ''had I known'', ''if it were not for'' vira ''were it not for'', e ''if you should require'' vira ''should you require''. Essa estrutura é comum em documentos jurídicos, discursos formais e correspondência de negócios.", "question": "Where is this inverted conditional structure common, according to the text?", "options": ["In legal documents, formal speeches and business correspondence", "Only in poetry", "Only in text messages"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000386', 'listening', 12, '{"audio_text": "Had I known about the delay, I would have left earlier. Were it not for her help, the project would have failed. Should you require further information, please contact us.", "question": "What would have happened without her help, according to the audio?", "options": ["The project would have failed", "The delay would have continued", "They would have contacted us"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000386', 'dictation', 13, '{"audio_text": "Had I known about the delay, I would have left earlier.", "expected": "Had I known about the delay, I would have left earlier."}'),
('20000000-0000-0000-0000-000000000386', 'typing', 14, '{"prompt_pt": "Traduza: ''Se eu tivesse sabido antes, teria agido diferente; se não fosse pela sua ajuda, eu não teria conseguido.''", "expected": "Had I known earlier, I would have acted differently; were it not for your help, I would not have succeeded.", "ai_review": true}'),

-- Lição 387: Inversão com advérbios negativos (rarely have I seen, never before has, not until, only then did, seldom do we, under no circumstances)
('20000000-0000-0000-0000-000000000387', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002317", "show_image": false}'),
('20000000-0000-0000-0000-000000000387', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002319", "show_image": false}'),
('20000000-0000-0000-0000-000000000387', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002322", "show_image": false}'),
('20000000-0000-0000-0000-000000000387', 'multiple_choice', 4, '{"question": "___ such a well-organized team.", "audio_text": null, "options": ["Rarely have I seen", "Only then did", "Seldom do we"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000387', 'multiple_choice', 5, '{"question": "___ the company faced such a challenge.", "audio_text": null, "options": ["Never before has", "Under no circumstances", "Not until"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000387', 'matching', 6, '{"pairs": [{"left": "rarely have I seen", "right": "raramente eu já vi"}, {"left": "never before has", "right": "nunca antes"}, {"left": "not until", "right": "somente quando"}, {"left": "only then did", "right": "só então"}, {"left": "seldom do we", "right": "raramente nós"}, {"left": "under no circumstances", "right": "em hipótese alguma"}]}'),
('20000000-0000-0000-0000-000000000387', 'fill_blank', 7, '{"sentence": "___ the results arrived did they understand the problem.", "options": ["Not until", "Only then did", "Rarely have I seen"], "correct": "Not until", "translation": "Somente quando os resultados chegaram é que eles entenderam o problema."}'),
('20000000-0000-0000-0000-000000000387', 'fill_blank', 8, '{"sentence": "___ should this document be shared externally.", "options": ["Under no circumstances", "Seldom do we", "Never before has"], "correct": "Under no circumstances", "translation": "Em hipótese alguma este documento deve ser compartilhado externamente."}'),
('20000000-0000-0000-0000-000000000387', 'word_order', 9, '{"words": ["Only", "then", "did", "she", "realize", "her", "mistake"], "correct_sentence": "Only then did she realize her mistake", "translation": "Só então ela percebeu o erro dela"}'),
('20000000-0000-0000-0000-000000000387', 'word_order', 10, '{"words": ["Seldom", "do", "we", "see", "such", "rapid", "progress", "in", "this", "field"], "correct_sentence": "Seldom do we see such rapid progress in this field", "translation": "Raramente vemos um progresso tão rápido nesta área"}'),
('20000000-0000-0000-0000-000000000387', 'reading', 11, '{"passage": "Negative adverbs like ''rarely'', ''never'', ''not until'', ''only'' and ''seldom'' can be placed at the start of a sentence for emphasis, but this requires inverting the subject and auxiliary verb, as in ''rarely have I seen'' or ''seldom do we see''. ''Under no circumstances'' works the same way, always followed by inverted word order, and is common in formal rules and warnings.", "translation": "Advérbios negativos como ''rarely'', ''never'', ''not until'', ''only'' e ''seldom'' podem ser colocados no início de uma frase para dar ênfase, mas isso exige a inversão do sujeito e do verbo auxiliar, como em ''rarely have I seen'' ou ''seldom do we see''. ''Under no circumstances'' funciona da mesma forma, sempre seguido de ordem invertida, e é comum em regras e avisos formais.", "question": "What is always required after these negative adverbs at the start of a sentence, according to the text?", "options": ["Inverted subject and auxiliary word order", "A question mark", "The passive voice"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000387', 'listening', 12, '{"audio_text": "Rarely have I seen such a well-organized team. Never before has the company faced such a challenge. Under no circumstances should this document be shared externally.", "question": "What should never be shared externally, according to the audio?", "options": ["This document", "The team", "The challenge"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000387', 'dictation', 13, '{"audio_text": "Never before has the company faced such a challenge.", "expected": "Never before has the company faced such a challenge."}'),
('20000000-0000-0000-0000-000000000387', 'typing', 14, '{"prompt_pt": "Traduza: ''Raramente eu já vi uma equipe tão dedicada; só então percebemos o quanto isso importava.''", "expected": "Rarely have I seen such a dedicated team; only then did we realize how much it mattered.", "ai_review": true}'),

-- Lição 388: Inversão de sequência e ênfase (little did he know, no sooner had... than, hardly had... when, only after, so great was, such was the impact)
('20000000-0000-0000-0000-000000000388', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002323", "show_image": false}'),
('20000000-0000-0000-0000-000000000388', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002324", "show_image": false}'),
('20000000-0000-0000-0000-000000000388', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002327", "show_image": false}'),
('20000000-0000-0000-0000-000000000388', 'multiple_choice', 4, '{"question": "___ that the decision would change everything.", "audio_text": null, "options": ["Little did he know", "Only after", "Such was the impact"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000388', 'multiple_choice', 5, '{"question": "___ she arrived than the meeting started.", "audio_text": null, "options": ["No sooner had", "Hardly had", "Only after"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000388', 'matching', 6, '{"pairs": [{"left": "little did he know", "right": "ele mal sabia"}, {"left": "no sooner had... than", "right": "mal... e já"}, {"left": "hardly had... when", "right": "mal... quando"}, {"left": "only after", "right": "somente depois de"}, {"left": "so great was", "right": "tão grande foi"}, {"left": "such was the impact", "right": "tal foi o impacto"}]}'),
('20000000-0000-0000-0000-000000000388', 'fill_blank', 7, '{"sentence": "___ he finished speaking when the phone rang.", "options": ["Hardly had", "No sooner had", "Only after"], "correct": "Hardly had", "translation": "Ele mal tinha terminado de falar quando o telefone tocou."}'),
('20000000-0000-0000-0000-000000000388', 'fill_blank', 8, '{"sentence": "___ the demand that the company doubled production.", "options": ["So great was", "Such was the impact", "Little did he know"], "correct": "So great was", "translation": "Tão grande foi a demanda que a empresa dobrou a produção."}'),
('20000000-0000-0000-0000-000000000388', 'word_order', 9, '{"words": ["Only", "after", "reviewing", "the", "data", "did", "they", "approve", "the", "plan"], "correct_sentence": "Only after reviewing the data did they approve the plan", "translation": "Somente depois de revisar os dados eles aprovaram o plano"}'),
('20000000-0000-0000-0000-000000000388', 'word_order', 10, '{"words": ["Such", "was", "the", "impact", "of", "the", "announcement", "that", "shares", "rose", "immediately"], "correct_sentence": "Such was the impact of the announcement that shares rose immediately", "translation": "Tal foi o impacto do anúncio que as ações subiram imediatamente"}'),
('20000000-0000-0000-0000-000000000388', 'reading', 11, '{"passage": "Inversion is also used for dramatic sequence and degree. ''Little did he know'', ''no sooner had... than'' and ''hardly had... when'' emphasize a surprising or sudden event. ''Only after'' delays the main clause for emphasis, while ''so great was'' and ''such was the impact'' highlight an extreme degree before explaining its result.", "translation": "A inversão também é usada para sequência e grau dramáticos. ''Little did he know'', ''no sooner had... than'' e ''hardly had... when'' enfatizam um evento surpreendente ou repentino. ''Only after'' atrasa a oração principal para dar ênfase, enquanto ''so great was'' e ''such was the impact'' destacam um grau extremo antes de explicar seu resultado.", "question": "What do phrases like ''little did he know'' emphasize, according to the text?", "options": ["A surprising or sudden event", "A routine, expected action", "A formal apology"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000388', 'listening', 12, '{"audio_text": "Little did he know that the decision would change everything. No sooner had she arrived than the meeting started. So great was the demand that the company doubled production.", "question": "What did the company do because of the great demand, according to the audio?", "options": ["Doubled production", "Cancelled the meeting", "Changed everything"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000388', 'dictation', 13, '{"audio_text": "Little did he know that the decision would change everything.", "expected": "Little did he know that the decision would change everything."}'),
('20000000-0000-0000-0000-000000000388', 'typing', 14, '{"prompt_pt": "Traduza: ''Ele mal sabia que, mal a reunião começou, tudo mudaria; tão grande foi o impacto.''", "expected": "Little did he know that, no sooner had the meeting started, everything would change; so great was the impact.", "ai_review": true}'),

