('20000000-0000-0000-0000-000000000389', 'matching', 6, '{"pairs": [{"left": "were it to happen", "right": "se isso viesse a acontecer"}, {"left": "had they realized", "right": "se eles tivessem percebido"}, {"left": "should the need arise", "right": "caso a necessidade surja"}, {"left": "were this the case", "right": "se esse fosse o caso"}, {"left": "had I been aware", "right": "se eu estivesse ciente"}, {"left": "should there be any doubt", "right": "caso haja alguma dúvida"}]}'),
('20000000-0000-0000-0000-000000000389', 'fill_blank', 7, '{"sentence": "___ the risk sooner, they could have avoided the loss.", "options": ["Had they realized", "Should the need arise", "Were this the case"], "correct": "Had they realized", "translation": "Se eles tivessem percebido o risco antes, poderiam ter evitado a perda."}'),
('20000000-0000-0000-0000-000000000389', 'fill_blank', 8, '{"sentence": "___, feel free to contact the office.", "options": ["Should there be any doubt", "Were it to happen", "Had I been aware"], "correct": "Should there be any doubt", "translation": "Caso haja alguma dúvida, sinta-se à vontade para contatar o escritório."}'),
('20000000-0000-0000-0000-000000000389', 'word_order', 9, '{"words": ["Were", "it", "to", "happen", "again", "the", "team", "would", "be", "better", "prepared"], "correct_sentence": "Were it to happen again the team would be better prepared", "translation": "Se isso viesse a acontecer de novo, a equipe estaria mais preparada"}'),
('20000000-0000-0000-0000-000000000389', 'word_order', 10, '{"words": ["Were", "this", "the", "case", "the", "entire", "strategy", "would", "need", "to", "change"], "correct_sentence": "Were this the case the entire strategy would need to change", "translation": "Se esse fosse o caso, toda a estratégia precisaria mudar"}'),
('20000000-0000-0000-0000-000000000389', 'reading', 11, '{"passage": "Formal hypothetical structures extend beyond the basic ''had I known'' pattern. ''Were it to happen'', ''were this the case'' and ''had they realized'' explore alternative scenarios in reports and analyses. ''Should the need arise'' and ''should there be any doubt'' are extremely common in formal instructions and contracts, signaling politely what will happen under a certain condition.", "translation": "Estruturas hipotéticas formais vão além do padrão básico ''had I known''. ''Were it to happen'', ''were this the case'' e ''had they realized'' exploram cenários alternativos em relatórios e análises. ''Should the need arise'' e ''should there be any doubt'' são extremamente comuns em instruções formais e contratos, sinalizando educadamente o que acontecerá sob certa condição.", "question": "Where are ''should the need arise'' and ''should there be any doubt'' extremely common, according to the text?", "options": ["In formal instructions and contracts", "In song lyrics", "In casual chat messages"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000389', 'listening', 12, '{"audio_text": "Should the need arise, additional staff will be hired. Had I been aware of the deadline, I would have finished sooner. Should there be any doubt, feel free to contact the office.", "question": "What will happen should the need arise, according to the audio?", "options": ["Additional staff will be hired", "The office will close", "The deadline will change"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000389', 'dictation', 13, '{"audio_text": "Should the need arise, additional staff will be hired.", "expected": "Should the need arise, additional staff will be hired."}'),
('20000000-0000-0000-0000-000000000389', 'typing', 14, '{"prompt_pt": "Traduza: ''Caso a necessidade surja, entraremos em contato; caso haja alguma dúvida, sinta-se à vontade para perguntar.''", "expected": "Should the need arise, we will get in touch; should there be any doubt, feel free to ask.", "ai_review": true}'),

-- Lição 390: Revisão final: frases de ênfase e certeza (it goes without saying that, needless to say, suffice it to say, it stands to reason that, in no way, under any circumstances)
('20000000-0000-0000-0000-000000000390', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002335", "show_image": false}'),
