('20000000-0000-0000-0000-000000000390', 'multiple_choice', 4, '{"question": "___ safety comes first.", "audio_text": null, "options": ["It goes without saying that", "In no way", "Suffice it to say"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000390', 'multiple_choice', 5, '{"question": "This decision ___ reflects a lack of confidence in the team.", "audio_text": null, "options": ["in no way", "needless to say", "under any circumstances"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000390', 'matching', 6, '{"pairs": [{"left": "it goes without saying that", "right": "nem precisa dizer que"}, {"left": "needless to say", "right": "desnecessário dizer"}, {"left": "suffice it to say", "right": "basta dizer que"}, {"left": "it stands to reason that", "right": "é lógico que"}, {"left": "in no way", "right": "de forma alguma"}, {"left": "under any circumstances", "right": "em qualquer circunstância"}]}'),
('20000000-0000-0000-0000-000000000390', 'fill_blank', 7, '{"sentence": "___, the results exceeded all expectations.", "options": ["Suffice it to say", "In no way", "It stands to reason that"], "correct": "Suffice it to say", "translation": "Basta dizer que os resultados superaram todas as expectativas."}'),
('20000000-0000-0000-0000-000000000390', 'fill_blank', 8, '{"sentence": "The rule applies ___, without exception.", "options": ["under any circumstances", "in no way", "needless to say"], "correct": "under any circumstances", "translation": "A regra se aplica em qualquer circunstância, sem exceção."}'),
('20000000-0000-0000-0000-000000000390', 'word_order', 9, '{"words": ["Needless", "to", "say", "the", "client", "was", "extremely", "satisfied"], "correct_sentence": "Needless to say the client was extremely satisfied", "translation": "Desnecessário dizer que o cliente ficou extremamente satisfeito"}'),
('20000000-0000-0000-0000-000000000390', 'word_order', 10, '{"words": ["It", "stands", "to", "reason", "that", "more", "training", "leads", "to", "better", "performance"], "correct_sentence": "It stands to reason that more training leads to better performance", "translation": "É lógico que mais treinamento leva a um desempenho melhor"}'),
('20000000-0000-0000-0000-000000000390', 'reading', 11, '{"passage": "This review closes the whole module on formal inversion and hypothetical structures. Alongside inverted conditionals like ''had I known'' and negative-adverb inversions like ''rarely have I seen'', formal English uses fixed emphatic phrases: ''it goes without saying that'', ''needless to say'' and ''suffice it to say'' introduce an obvious or strong point, ''it stands to reason that'' signals logical certainty, and ''in no way'' and ''under any circumstances'' express absolute denial or condition. Together, these structures mark the highest, most formal register of C1 English.", "translation": "Esta revisão fecha todo o módulo de inversão formal e estruturas hipotéticas. Junto com condicionais invertidas como ''had I known'' e inversões com advérbios negativos como ''rarely have I seen'', o inglês formal usa frases fixas de ênfase: ''it goes without saying that'', ''needless to say'' e ''suffice it to say'' introduzem um ponto óbvio ou forte, ''it stands to reason that'' sinaliza certeza lógica, e ''in no way'' e ''under any circumstances'' expressam negação ou condição absoluta. Juntas, essas estruturas marcam o registro mais alto e formal do inglês C1.", "question": "According to the text, what do ''in no way'' and ''under any circumstances'' express?", "options": ["Absolute denial or condition", "Uncertainty and doubt", "A casual suggestion"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000390', 'listening', 12, '{"audio_text": "It goes without saying that safety comes first. Suffice it to say, the results exceeded all expectations. The rule applies under any circumstances, without exception.", "question": "What comes first, according to the audio?", "options": ["Safety", "The results", "The rule"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000390', 'dictation', 13, '{"audio_text": "It goes without saying that safety comes first.", "expected": "It goes without saying that safety comes first."}'),
('20000000-0000-0000-0000-000000000390', 'typing', 14, '{"prompt_pt": "Traduza: ''É lógico que a segurança vem primeiro; basta dizer que, de forma alguma, isso vai mudar.''", "expected": "It stands to reason that safety comes first; suffice it to say, this will in no way change.", "ai_review": true}'),
('20000000-0000-0000-0000-000000000390', 'typing', 15, '{"prompt_pt": "Traduza: ''Se eu tivesse sabido antes, e caso a necessidade surja novamente, agirei imediatamente, em qualquer circunstância.''", "expected": "Had I known earlier, and should the need arise again, I will act immediately, under any circumstances.", "ai_review": true}');

